/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/**
 * @method
 * @name $
 * @description desc
 * @param {string} id desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.$ = function(id) {
    return document.getElementById(id);
};


/**
 * 출처 - http://blog.daum.net/lhd720904/13754882
 * 감사합니다.
 */
/**
 * @method
 * @name formData2QueryString
 * @description desc
 * @param {string} docForm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.formData2QueryString = function(docForm) {
    var strSubmitContent = '';
    var formElem;
    var strLastElemName = '';
    for (i = 0; i < docForm.elements.length; i++) {
        formElem = docForm.elements[i];
        switch (formElem.type) {
            case 'text':
            case 'hidden':
            case 'password':
            case 'textarea':
            case 'select-one':
                strSubmitContent += formElem.name + '=' + encodeURIComponent(formElem.getValue()) + '&';
                break;
            case 'radio':
                if (formElem.checked) strSubmitContent += formElem.name + '=' + encodeURIComponent(formElem.getValue()) + '&';
                break;
            case 'checkbox':
                if (formElem.checked) {
                    // Continuing multiple, same-name checkboxes
                    /*	if (formElem.name == strLastElemName)
                    	{
                    		// Strip of end ampersand if there is one
                    		if (strSubmitContent.lastIndexOf('&') == strSubmitContent.length-1)
                    		{
                    			strSubmitContent = strSubmitContent.substr(0, strSubmitContent.length - 1);
                    		}
                    		// Append value as comma-delimited string
                    		strSubmitContent += ',' + encodeURIComponent(formElem.value);
                    	}
                    	else
                    	{*/
                    strSubmitContent += formElem.name + '=' + encodeURIComponent(formElem.getValue());
                    //	}
                    strSubmitContent += '&';
                    strLastElemName = formElem.name;
                }
                break;
        }
    }

    // Remove trailing separator
    strSubmitContent = strSubmitContent.substr(0, strSubmitContent.length - 1);
    return strSubmitContent;
};
xmlHttp;
/**
 * @method
 * @name getXMLHttpRequest
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getXMLHttpRequest = function() {
    try {
        scwin.xmlHttp = new ActiveXObject("Msxml2.XMLHTTP");
    } catch (e) {
        try {
            scwin.xmlHttp = new ActiveXObject("Microsoft.XMLHTTP");
        } catch (sc) {
            scwin.xmlHttp = null;
        }
    }
    if (!scwin.xmlHttp && typeof XMLHttpRequest != "undefined") scwin.xmlHttp = new XMLHttpRequest();
    return scwin.xmlHttp;
};
/**
 * @method
 * @name requestXMLHTTP
 * @description desc
 * @param {string} _form desc
 * @param {string} _method desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.requestXMLHTTP = function(_form, _method) {
    scwin.sendMessage(_form, _method, responseHandler);
    /**
     * @method
     * @name responseHandler
     * @description desc
     * @param
     * @returns
     * @hidden N
     * @exception
     * @example
     */
    function responseHandler() {
        if (xmlHttp.readyState == 4) // complete
            scwin.onCompleteResponse(xmlHttp.responseText);
    };
    return false;
};
/**
 * @method
 * @name responseTextXMLHTTP
 * @description desc
 * @param {string} _form desc
 * @param {string} _method desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.responseTextXMLHTTP = function(_form, _method) {
    scwin.sendMessage(_form, _method, responseHandler);
    var text;
    /**
     * @method
     * @name responseHandler
     * @description desc
     * @param
     * @returns
     * @hidden N
     * @exception
     * @example
     */
    function responseHandler() {
        if (xmlHttp.readyState == 4) // complete
            text.setValue(xmlHttp.responseText);
    };
    return text;
};
/**
 * @method
 * @name sendMessage
 * @description desc
 * @param {string} _form desc
 * @param {string} _method desc
 * @param {string} responseHandler desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.sendMessage = function(_form, _method, responseHandler) {
    var _url = _form.action;
    // method라는 input엘리먼트가 존재.. ㅡ,.ㅡ
    //var _method = _form.method;

    if (!_method) _method = "GET";
    var _params = "";
    var _elements = _form.elements;
    for (var i = 0; i < _elements.length; i++) {
        if (_elements[i].name != "") {
            if (_params != "") _params = _params + "&";
            _params = _params + _elements[i].name + "=" + encodeURIComponent(_elements[i].getValue());
            //_params = _params + _elements[i].name + "=" + _elements[i].value;

        }
    }
    if (_method == "get") {
        if (_url.indexOf("?") > 0) _url = _url + "&" + _params;

        else _url = _url + "?" + _params;
    } else {
        _params = scwin.formData2QueryString(_form);
    }
    if (_url == "") _url = "?";
    if (scwin.xmlHttp == null) scwin.xmlHttp = scwin.getXMLHttpRequest();

    // 동기
    xmlHttp.open(_method, _url, false);
    xmlHttp.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");
    xmlHttp.setRequestHeader("Cache-Control", "no-cache, must-revalidate");
    xmlHttp.setRequestHeader("Pragma", "no-cache");
    xmlHttp.onreadystatechange = responseHandler;
    xmlHttp.send(_params);
};
/**
 * @method
 * @name onCompleteResponse
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.onCompleteResponse = function() {

};
